import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { basename, dirname, extname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import test from "node:test";

const repoRoot = dirname(dirname(fileURLToPath(import.meta.url)));

const profilePaths = {
	full: "packages/my-pi-full/package.json",
	harness: "packages/my-pi-harness/package.json",
	pod: "packages/my-pi-pod/package.json",
};

function readText(path) {
	return readFileSync(join(repoRoot, path), "utf8");
}

function readJson(path) {
	return JSON.parse(readText(path));
}

function extensionPath(extension) {
	return typeof extension === "string" ? extension : extension?.path;
}

function extensionIdFromPath(rawPath) {
	if (!rawPath || typeof rawPath !== "string") return null;
	const normalized = rawPath.replaceAll("\\", "/");
	const parts = normalized.split("/").filter(Boolean);

	const packagesIndex = parts.lastIndexOf("packages");
	if (packagesIndex !== -1 && parts[packagesIndex + 1]) return parts[packagesIndex + 1];
	if (parts[0] === ".." && parts[1] && parts[1] !== "..") return parts[1];

	const extensionsIndex = parts.lastIndexOf("extensions");
	const relevant = extensionsIndex === -1 ? parts : parts.slice(extensionsIndex + 1);
	if (relevant[0] === "observability" && relevant[1]) {
		return `observability/${basename(relevant.at(-1), extname(relevant.at(-1)))}`;
	}
	return relevant[0] ?? null;
}

function profile(name) {
	const manifest = readJson(profilePaths[name]);
	const extensionIds = (manifest.pi?.extensions ?? []).map((entry) => extensionIdFromPath(extensionPath(entry)));
	const packageIds = manifest.pi?.packages ?? [];
	return { manifest, extensionIds, packageIds };
}

function indexOfExtension(name, id) {
	return profile(name).extensionIds.indexOf(id);
}

test("runtime profile manifests pass the membership validator", () => {
	const output = execFileSync("node", ["scripts/check-profiles.mjs"], {
		cwd: repoRoot,
		encoding: "utf8",
		stdio: ["ignore", "pipe", "pipe"],
	});
	assert.match(output, /Profile validation passed\./);
});

test("cache-critical skill/tool stack is profile-owned", () => {
	for (const name of ["full", "harness"]) {
		const ids = profile(name).extensionIds;
		assert(ids.includes("skill-loader"), `${name} profile loads skill-loader`);
		assert(ids.includes("tool-search"), `${name} profile loads tool-search`);
		assert(
			indexOfExtension(name, "skill-loader") < indexOfExtension(name, "tool-search"),
			`${name} profile stabilizes skill index before tool-search appends deferred-tool hints`,
		);
	}

	const pod = profile("pod");
	assert(!pod.extensionIds.includes("skill-loader"), "pod profile does not mutate systemPrompt:build");
	assert(!pod.extensionIds.includes("tool-search"), "pod profile does not mutate tools[]");
	assert(!pod.extensionIds.includes("dream-memory"), "pod profile does not load per-turn memory injection");
});

test("full profile registers native aliases before tool-search indexes tools", () => {
	const aliasIndex = indexOfExtension("full", "native-tool-aliases");
	const toolSearchIndex = indexOfExtension("full", "tool-search");
	assert(aliasIndex >= 0, "full profile loads native-tool-aliases");
	assert(toolSearchIndex >= 0, "full profile loads tool-search");
	assert(aliasIndex < toolSearchIndex, "native aliases register before tool-search builds the catalog");
});

test("profile packages do not duplicate cache-critical extensions", () => {
	for (const name of Object.keys(profilePaths)) {
		const ids = profile(name).extensionIds;
		for (const id of ["skill-loader", "tool-search", "dream-memory"]) {
			assert.equal(ids.filter((entry) => entry === id).length, ids.includes(id) ? 1 : 0, `${name} has at most one ${id}`);
		}
	}
});

test("cache-critical source comments stay attached to hooks and filters", () => {
	const skillLoader = readText("extensions/skill-loader/src/index.ts");
	assert.match(skillLoader, /CACHE CRITICAL: systemPrompt:build affects the stable system-prompt prefix\./);
	assert.match(skillLoader, /must never add per-message\/session[\s/]+dynamic data/);
	assert.match(skillLoader, /dynamic skill or recall material belongs after Pi's[\s/]+system-prompt cache boundary or in an appended message\/tool result/);

	const toolSearch = readText("extensions/tool-search/src/index.ts");
	assert.match(toolSearch, /CACHE CRITICAL: this hook rewrites the system prompt and active tool[\s/]+list/);
	assert.match(toolSearch, /CACHE CRITICAL: tools\[\] is a provider request parameter/);

	const dreamMemory = readText("extensions/dream-memory/src/extension.ts");
	assert.match(dreamMemory, /CACHE CRITICAL:/);
	assert.match(dreamMemory, /stale[\s/]+dream-memory\.active-recall/);
});

test("profile docs mention every profile package", () => {
	const inventory = readText("docs/pi-runtime-profiles.md");
	for (const path of Object.values(profilePaths)) {
		const name = readJson(path).name;
		assert.match(inventory, new RegExp(`\\b${name}\\b`), `${relative(repoRoot, join(repoRoot, path))} is documented`);
	}
});

