import assert from "node:assert/strict";
import test from "node:test";
import { createJiti } from "jiti";

const jiti = createJiti(import.meta.url, { interopDefault: true, fsCache: false });
const { normalizeToolName } = await jiti.import("../extensions/tool-search/src/catalog.ts");

const THRESHOLDS = {
  maxTotalPromptTokens: 30_000,
  maxActiveTools: 12,
  maxAvailableSkillsBytes: 8_000,
};

function auditPromptDump(dump) {
  const messages0 = String(dump.messages?.[0]?.content ?? "");
  const activeTools = (dump.tools ?? []).map((tool) => String(tool.name));
  const activeCapabilities = new Set(activeTools.map(normalizeToolName));
  const deferredCapabilities = parseDeferredTools(messages0).map(normalizeToolName);
  const duplicateCapabilities = [...new Set(deferredCapabilities.filter((name) => activeCapabilities.has(name)))].sort();
  const availableSkills = extractBlock(messages0, "available_skills");
  const payloadBytes = Buffer.byteLength(JSON.stringify(dump));

  return {
    estTotalTokens: Math.floor(payloadBytes / 4),
    activeToolCount: activeTools.length,
    nativeDeferredToolCount: (dump.tools ?? []).filter((tool) => tool.defer_loading === true).length,
    duplicateCapabilities,
    inlineSkillBodyHits: (messages0.match(/^# SKILL\b|^# Skill\b/gm) ?? []).length,
    multilineSkillBlocks: countMultilineSkillBlocks(messages0),
    availableSkillsBytes: Buffer.byteLength(availableSkills),
  };
}

function promptHealthWarnings(audit) {
  const warnings = [];
  if (audit.estTotalTokens > THRESHOLDS.maxTotalPromptTokens) {
    warnings.push("total_prompt_over_soft_cap");
  }
  if (audit.activeToolCount > THRESHOLDS.maxActiveTools) {
    warnings.push("active_tool_schema_budget_exceeded");
  }
  if (audit.duplicateCapabilities.length > 0) {
    warnings.push("active_deferred_double_billing");
  }
  if (audit.nativeDeferredToolCount === 0 && audit.activeToolCount > 5) {
    warnings.push("native_deferred_missing");
  }
  if (audit.inlineSkillBodyHits > 0 || audit.multilineSkillBlocks > 0) {
    warnings.push("inline_skill_body");
  }
  if (audit.availableSkillsBytes > THRESHOLDS.maxAvailableSkillsBytes) {
    warnings.push("available_skills_over_budget");
  }
  return warnings;
}

function parseDeferredTools(text) {
  const block = extractBlock(text, "deferred-tools");
  return [...block.matchAll(/^- ([A-Za-z_][A-Za-z0-9_]*)/gm)].map((match) => match[1]);
}

function extractBlock(text, tag) {
  const open = `<${tag}>`;
  const close = `</${tag}>`;
  const openIndex = text.indexOf(open);
  if (openIndex < 0) return "";
  const closeIndex = text.indexOf(close, openIndex);
  if (closeIndex < 0) return text.slice(openIndex + open.length);
  return text.slice(openIndex + open.length, closeIndex);
}

function countMultilineSkillBlocks(text) {
